#!/usr/bin/env node
/**
 * usage-throttle.js — Graduated 4-zone token budget throttle for Claude Code pipelines.
 *
 * Reads weekTotal.estimatedCostUSD + nextResetAt from data/claude-usage-cache.json
 * (generated by usage-stats.js) and computes a current zone:
 *
 *   sprint        0 –  30%   full speed, no per-agent throttle
 *   cruise       30 –  65%   developer / reviewer 25 min, others normal
 *   conservation 65 –  85%   developer 45 / reviewer 60 / pm 2h
 *   minimal      85+         most agents 3h, pm/pdm/auditor 6h+
 *
 * Outputs (read by preflight-gate.sh):
 *
 *   ZONE                            Current zone (sprint|cruise|conservation|minimal),
 *                                    plus key=value metadata lines (pct, mode, updated).
 *   THROTTLE_INTERVAL_<AGENT>       Minimum minutes between runs for this agent in
 *                                    the current zone. Absent file = no throttle.
 *   THROTTLE_SOFT / THROTTLE_HARD   Back-compat with the original 2-tier API.
 *                                    SOFT is set in conservation+, HARD in minimal.
 *   throttle-history.jsonl          Append-only audit trail (one JSON line per tick).
 *
 * Inputs (manual):
 *
 *   FAST_MODE                       Touch this file in the runtime dir to force
 *                                    Sprint zone regardless of usage. Useful for
 *                                    "burn through this push" sessions.
 *
 * End-of-week behavior:
 *
 *   - 48–24h pre-reset, pct < 65% → FLOOR to Cruise. Stops you from under-spending
 *     the budget you already paid for.
 *   - Final 24h, leftover% / hours-left > 1%/h → FORCE Sprint. Burns remaining
 *     budget on real work instead of leaving it on the floor.
 *
 * Hysteresis: zone boundaries have a 2pt buffer on the way down so the system
 * doesn't flap between zones near a threshold.
 *
 * Environment:
 *
 *   WORKSPACE_DIR              Project root (default: process.cwd()).
 *   THROTTLE_RUNTIME_DIR       Runtime signal directory (default: data/runtime).
 *   USAGE_CACHE_FILE           Cache JSON (default: data/claude-usage-cache.json).
 *   WEEKLY_USD_BUDGET          Weekly budget in API-equivalent USD (default: 1700).
 *   THROTTLE_AGENT_NAMES       Comma-separated agent names to write interval files
 *                              for (default covers the autonomous-dev-agents-system
 *                              standard set).
 *   DISCORD_POST_SCRIPT        Optional script: node <path> <channel_id> <message>
 *   DISCORD_CHANNEL_ID         Channel for zone-transition alerts.
 *
 * Schedule: run every 30 min via cron-framework (runner: "shell").
 */

'use strict';

const fs   = require('fs');
const path = require('path');

const WORKSPACE = process.env.WORKSPACE_DIR || process.cwd();

// Load .env if present
try {
  fs.readFileSync(path.join(WORKSPACE, '.env'), 'utf8')
    .split('\n').forEach(l => {
      const m = l.match(/^([A-Z_][A-Z0-9_]*)=(.*)/);
      if (m && !process.env[m[1]]) process.env[m[1]] = m[2].trim();
    });
} catch {}

const RUNTIME    = process.env.THROTTLE_RUNTIME_DIR || path.join(WORKSPACE, 'data/runtime');
const CACHE_FILE = process.env.USAGE_CACHE_FILE     || path.join(WORKSPACE, 'data/claude-usage-cache.json');
const ZONE_FILE  = path.join(RUNTIME, 'ZONE');
const SOFT_FILE  = path.join(RUNTIME, 'THROTTLE_SOFT');
const HARD_FILE  = path.join(RUNTIME, 'THROTTLE_HARD');
const FAST_FILE  = path.join(RUNTIME, 'FAST_MODE');
const HISTORY    = path.join(RUNTIME, 'throttle-history.jsonl');

const BUDGET = parseFloat(process.env.WEEKLY_USD_BUDGET || '1700');

// Zone boundaries (% of weekly budget). Hysteresis: 2pt buffer at each edge.
const ZONES = ['sprint', 'cruise', 'conservation', 'minimal'];
const ENTER = { sprint: 0,    cruise: 0.30, conservation: 0.65, minimal: 0.85 };
const EXIT  = { sprint: 0.28, cruise: 0.63, conservation: 0.83, minimal: 1.01 };

// Per-agent minimum minutes between runs in each zone. 0 = no throttle this zone.
// The default agent set matches autonomous-dev-agents-system. Override the list of
// agents (not the intervals) via THROTTLE_AGENT_NAMES env var.
const DEFAULT_AGENTS = [
  'developer', 'reviewer', 'trd_watcher', 'merge_watcher',
  'pr_ci_fixer', 'main_ci_fixer',
  'project_manager', 'product_manager', 'codebase_auditor',
];

const INTERVALS = {
  sprint: { developer: 0, reviewer: 0, trd_watcher: 0, merge_watcher: 0, pr_ci_fixer: 0, main_ci_fixer: 0, project_manager: 0, product_manager: 0, codebase_auditor: 0 },
  cruise: { developer: 25, reviewer: 25, trd_watcher: 15, merge_watcher: 15, pr_ci_fixer: 5, main_ci_fixer: 5, project_manager: 30, product_manager: 0, codebase_auditor: 0 },
  conservation: { developer: 45, reviewer: 60, trd_watcher: 45, merge_watcher: 30, pr_ci_fixer: 15, main_ci_fixer: 30, project_manager: 120, product_manager: 360, codebase_auditor: 360 },
  minimal: { developer: 180, reviewer: 180, trd_watcher: 180, merge_watcher: 180, pr_ci_fixer: 180, main_ci_fixer: 180, project_manager: 360, product_manager: 720, codebase_auditor: 720 },
};

const AGENT_NAMES = (process.env.THROTTLE_AGENT_NAMES || DEFAULT_AGENTS.join(','))
  .split(',').map(s => s.trim()).filter(Boolean);

function readCache() {
  try { return JSON.parse(fs.readFileSync(CACHE_FILE, 'utf8')); }
  catch { return null; }
}

function getWeeklyEstimatedCost(cache) {
  return (cache && cache.weekTotal && cache.weekTotal.estimatedCostUSD) || 0;
}

// hours until next reset per the cache; usage-stats.js writes nextResetAt as ISO.
// Falls back to "infinity" if missing — overrides will simply not fire.
function hoursUntilReset(cache) {
  const iso = cache && cache.nextResetAt;
  if (!iso) return Infinity;
  const t = Date.parse(iso);
  if (isNaN(t)) return Infinity;
  return Math.max(0, (t - Date.now()) / 3600000);
}

// Compute zone from pct, applying hysteresis against the previously-recorded
// zone so we don't flap at the boundary.
function pickZone(pct, prev) {
  let target = 'sprint';
  for (const z of ZONES) {
    if (pct >= ENTER[z]) target = z;
  }
  if (!prev || target === prev) return target;
  const prevIdx = ZONES.indexOf(prev);
  const tgtIdx = ZONES.indexOf(target);
  if (tgtIdx < prevIdx) {
    if (pct < EXIT[prev]) return target;
    return prev;
  }
  return target;
}

// End-of-week + FAST_MODE overrides.
function applyOverrides(zone, pct, hrsLeft) {
  if (fs.existsSync(FAST_FILE)) return { zone: 'sprint', mode: 'fast' };
  if (hrsLeft < 24 && hrsLeft > 0) {
    const burnRate = (1 - pct) * 100 / hrsLeft;
    if (burnRate > 1.0) return { zone: 'sprint', mode: 'eow-burn' };
  }
  if (hrsLeft >= 24 && hrsLeft <= 48 && pct < 0.65) {
    const idx = ZONES.indexOf(zone);
    const cIdx = ZONES.indexOf('cruise');
    if (idx < cIdx) return { zone: 'cruise', mode: 'eow-floor' };
  }
  return { zone, mode: null };
}

function readPrevZone() {
  try { return fs.readFileSync(ZONE_FILE, 'utf8').trim().split('\n')[0]; }
  catch { return null; }
}

function writeZoneFile(zone, pct, mode) {
  const lines = [
    zone,
    `pct=${(pct * 100).toFixed(1)}`,
    `mode=${mode || 'normal'}`,
    `updated=${new Date().toISOString()}`,
  ];
  fs.writeFileSync(ZONE_FILE, lines.join('\n') + '\n');
}

function writeIntervalFiles(zone) {
  const intervals = INTERVALS[zone] || INTERVALS.sprint;
  for (const agent of AGENT_NAMES) {
    const mins = intervals[agent] || 0;
    const p = path.join(RUNTIME, `THROTTLE_INTERVAL_${agent.toUpperCase()}`);
    if (mins > 0) fs.writeFileSync(p, String(mins) + '\n');
    else if (fs.existsSync(p)) fs.unlinkSync(p);
  }
}

// Back-compat with the original 2-tier API: legacy preflight gates that only
// know about THROTTLE_SOFT / THROTTLE_HARD continue to work unchanged.
//   conservation+ → SOFT
//   minimal       → HARD
function writeLegacyFiles(zone, pct) {
  const wantSoft = zone === 'conservation' || zone === 'minimal';
  const wantHard = zone === 'minimal';
  if (wantSoft && !fs.existsSync(SOFT_FILE)) fs.writeFileSync(SOFT_FILE, `zone=${zone} pct=${(pct*100).toFixed(1)}\n`);
  if (!wantSoft && fs.existsSync(SOFT_FILE)) fs.unlinkSync(SOFT_FILE);
  if (wantHard && !fs.existsSync(HARD_FILE)) fs.writeFileSync(HARD_FILE, `zone=${zone} pct=${(pct*100).toFixed(1)}\n`);
  if (!wantHard && fs.existsSync(HARD_FILE)) fs.unlinkSync(HARD_FILE);
}

function appendHistory(zone, pct, mode) {
  const entry = JSON.stringify({ ts: new Date().toISOString(), zone, pct: +(pct * 100).toFixed(2), mode: mode || null }) + '\n';
  try { fs.appendFileSync(HISTORY, entry); } catch {}
}

function postDiscord(msg) {
  const script  = process.env.DISCORD_POST_SCRIPT;
  const channel = process.env.DISCORD_CHANNEL_ID;
  if (!script || !channel) return;
  try {
    const { spawnSync } = require('child_process');
    spawnSync('node', [script, channel, msg], { cwd: WORKSPACE, timeout: 5000 });
  } catch {}
}

const ZONE_EMOJI = { sprint: '🚀', cruise: '✈️', conservation: '🐢', minimal: '🔴' };

function main() {
  fs.mkdirSync(RUNTIME, { recursive: true });

  const cache = readCache();
  const used = getWeeklyEstimatedCost(cache);
  const pct = used / BUDGET;
  const prevZone = readPrevZone();
  const baseZone = pickZone(pct, prevZone);
  const hrsLeft = hoursUntilReset(cache);
  const { zone, mode } = applyOverrides(baseZone, pct, hrsLeft);

  writeZoneFile(zone, pct, mode);
  writeIntervalFiles(zone);
  writeLegacyFiles(zone, pct);
  appendHistory(zone, pct, mode);

  if (prevZone && prevZone !== zone) {
    const e = ZONE_EMOJI[zone] || '⚙️';
    const modeStr = mode ? ` (${mode})` : '';
    const hrsStr = isFinite(hrsLeft) ? `${hrsLeft.toFixed(1)}h until reset` : 'reset time unknown';
    postDiscord(`${e} **Throttle Zone: ${zone.toUpperCase()}**${modeStr} — ${(pct * 100).toFixed(1)}% of weekly budget ($${used.toFixed(0)} / $${BUDGET}). ${hrsStr}.`);
  }

  const hrsStr = isFinite(hrsLeft) ? hrsLeft.toFixed(1) : '?';
  console.log(`[usage-throttle] $${used.toFixed(0)} / $${BUDGET} (${(pct * 100).toFixed(1)}%) zone=${zone}${mode ? ' mode=' + mode : ''} hrs_to_reset=${hrsStr}`);
}

main();
